        clause = [(lit, '¬')]
        clauses.append(clause)

    # Generate clauses for each pair of literals
    for i in range(d):
        for j in range(i + 1, d):
            clause1 = [(literals[i], '¬'), (literals[j])]
            clause2 = [(literals[i]), (literals[j], '¬')]
            clauses.append(clause1)
            clauses.append(clause2)

    # Generate the final clause
    final_clause = []
    for lit in literals:
        final_clause.append((lit, '¬'))
    clauses.append(final_clause)

    return clauses

def adjacency_matrix(clauses: list) -> list:
    d = len(clauses)
    A = [[0] * d for _ in range(d)]

    for i in range(d):
        for j in range(i + 1, d):
            if any(lit in clauses[i] and '¬' not in lit for lit in clauses[j]):
                A[i][j], A[j][i] = 1, 1

    return A

